/// <summary>
/// PricingAttribute of table <c>CustTable</c> field MarkupGroup.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, MarkupGroup))]
internal class GUPPricingAttributeCustTableMarkupGroup extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable    custTable;
    MarkupGroup  markupGroup;

    while select MarkupGroup from custtable
        group by MarkupGroup
        join markupGroup
        group by GroupId, Module, Txt
        where custTable.MarkupGroup == markupGroup.GroupId && markupGroup.Module == MarkupModuleType::Cust
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(markupGroup.GroupId, markupGroup.Txt);
        ret.add(valueObject);
    }
    return ret;
}
